    <script>
      // Set form timestamp (spam protection expects form_ts)
      document.addEventListener('DOMContentLoaded', function(){
        var ts = document.querySelector('input[name="form_ts"]');
        if (ts) { ts.value = Math.floor(Date.now() / 1000); }

        // "Select package" buttons pre-fill dropdown + scroll to form
        document.querySelectorAll('a.btn-select').forEach(function(btn){
          btn.addEventListener('click', function(e){
            var pkgName = btn.getAttribute('data-package');
            var pkgPrice = btn.getAttribute('data-price');
            var sel = document.getElementById('li_package');
            if (sel && pkgName) {
              // Match e.g. "Starter (Rs 30,000/month)"
              for (var i = 0; i < sel.options.length; i++) {
                if (sel.options[i].value.indexOf(pkgName) === 0) { sel.selectedIndex = i; break; }
              }
            }
          });
        });

        // Submit handler — AJAX POST
        var form = document.getElementById('li-package-form');
        if (form) {
          form.addEventListener('submit', function(e){
            e.preventDefault();
            var fd = new FormData(form);
            var successBox = document.getElementById('li-form-success');
            var errorBox = document.getElementById('li-form-error');
            successBox.style.display = 'none';
            errorBox.style.display = 'none';
            fetch('/leadCaptureMail.php', {method:'POST', body: fd})
              .then(function(r){ return r.json(); })
              .then(function(data){
                if (data && data.status === 'success') {
                  form.style.display = 'none';
                  successBox.style.display = 'block';
                  if (window.gtag) gtag('event','linkedin_pb_package_enquiry', {package: fd.get('package') || 'not_selected'});
                } else {
                  errorBox.style.display = 'block';
                }
              })
              .catch(function(){ errorBox.style.display = 'block'; });
          });
        }
      });
    </script>

